const oldMatch=gMatchesJob;const taskFilter=document.createElement('select');taskFilter.id='stTaskStatus';taskFilter.setAttribute('aria-label','任务状态');taskFilter.innerHTML='<option value="all">全部任务状态</option><option value="running">进行中</option><option value="attention">需要处理</option><option value="done">已完成</option>';$('gSearch').after(taskFilter);taskFilter.onchange=()=>{gv.page=1;renderJobs(true)};
