document.querySelectorAll('[data-st-next],[data-st-back]').forEach(b=>b.onclick=()=>{const name=b.dataset.stNext||b.dataset.stBack;st[name]=Math.max(1,Math.min(3,st[name]+(b.dataset.stNext?1:-1)));stUpdate();window.scrollTo(0,0)});
