/* Discreet material favorites and tags. Bundled into studio.js for active jobs. */
(()=>{
const key='papapai-material-marks-v1';let local={},syncing=false,seq=0;
try{local=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){notice('收藏记录暂时无法读取，请检查浏览器存储',true)}
const views=[{id:'library',modal:'stMaterialLibrary'},{id:'products',modal:'stProducts'}];
function meta(a){const l=local[a.id];return l&&(l.pending||!state.health?.materialMarks)?l:{favorite:!!a.favorite,tags:a.tags||[]}}
function store(){try{localStorage.setItem(key,JSON.stringify(local));return true}catch(e){notice('浏览器无法保存收藏，请检查存储空间',true);return false}}
function toolbar(v){if(v.bar)return;const box=document.createElement('div');box.className='mm-toolbar';box.innerHTML='<div class="mm-tabs"><button type="button" class="active" data-filter="all">全部素材</button><button type="button" data-filter="favorites">星标收藏</button></div><input type="search" placeholder="搜索名称或标签" aria-label="搜索素材名称或标签"><select aria-label="按素材标签筛选"><option value="">全部标签</option></select><span class="mm-count"></span>';$(v.id).before(box);v.bar=box;v.filter='all';box.addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;v.filter=b.dataset.filter;box.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});filter(v)});box.querySelector('input').oninput=()=>filter(v);box.querySelector('select').onchange=()=>filter(v);const empty=document.createElement('div');empty.className='mm-empty';empty.hidden=true;empty.textContent='没有符合条件的素材，试试其他关键词或标签。';$(v.id).after(empty);v.empty=empty}
function filter(v){const q=v.bar.querySelector('input').value.trim().toLocaleLowerCase(),tag=v.bar.querySelector('select').value;let shown=0,total=0;$(v.id).querySelectorAll('[data-mm-id]').forEach(card=>{const a=state.assets.find(x=>x.id===card.dataset.mmId);if(!a)return;const m=meta(a);total++;card.hidden=(v.filter==='favorites'&&!m.favorite)||(tag&&!m.tags.includes(tag))||!!(q&&!([a.name,...m.tags].join(' ').toLocaleLowerCase().includes(q)));if(!card.hidden)shown++});v.bar.querySelector('.mm-count').textContent=shown+' / '+total+' 张';v.empty.hidden=shown>0||total===0}
function decorate(){for(const v of views){if(!$(v.id)||!$(v.modal))continue;toolbar(v);const select=v.bar.querySelector('select'),value=select.value;const tags=[...new Set(state.assets.filter(a=>a.transparent&&!a.trashed&&a.kind!=='scene'&&a.kind!=='result_scene').flatMap(a=>meta(a).tags))].sort((a,b)=>a.localeCompare(b,'zh'));select.innerHTML='<option value="">全部标签</option>'+tags.map(t=>'<option value="'+esc(t)+'">'+esc(t)+'</option>').join('');select.value=tags.includes(value)?value:'';
for(const card of $(v.id).querySelectorAll(v.id==='library'?'.art':'.pick')){const id=card.querySelector('[data-source]')?.dataset.source||card.querySelector('[data-product]')?.dataset.product;const a=state.assets.find(x=>x.id===id);if(!a)continue;card.dataset.mmId=id;const m=meta(a);card.querySelector('.mm-tools')?.remove();card.querySelector('.mm-chips')?.remove();const tools=document.createElement('div');tools.className='mm-tools';tools.innerHTML='<button type="button" data-mm-star="'+id+'" class="mm-star '+(m.favorite?'on':'')+'" aria-label="'+(m.favorite?'取消收藏':'收藏素材')+'" aria-pressed="'+!!m.favorite+'" title="'+(m.favorite?'取消收藏':'收藏素材')+'">'+(m.favorite?'★':'☆')+'</button><button type="button" data-mm-tag="'+id+'" class="mm-tag" aria-label="编辑素材标签" title="编辑标签"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M3 3h8l10 10-8 8L3 11z"/><circle cx="7.5" cy="7.5" r="1"/></svg></button>';card.append(tools);if(m.tags.length){const chips=document.createElement('div');chips.className='mm-chips';chips.title=m.tags.join('、');chips.innerHTML=m.tags.slice(0,2).map(t=>'<span>'+esc(t)+'</span>').join('')+(m.tags.length>2?'<span>+'+(m.tags.length-2)+'</span>':'');const title=card.querySelector(v.id==='library'?'.art-info b':'small');title?.after(chips)}}filter(v)}}
function change(id,values){const a=state.assets.find(x=>x.id===id);if(!a)return;const previous=local[id];local[id]={...meta(a),...values,pending:true,rev:Date.now()+':'+(++seq)};if(!store()){if(previous)local[id]=previous;else delete local[id];return false}decorate();sync();return true}
async function sync(){if(syncing||!state.health?.materialMarks)return;syncing=true;try{for(const [id,m] of Object.entries(local)){if(!m.pending||!state.assets.some(a=>a.id===id))continue;const rev=m.rev;const result=await api('/api/material-marks',{asset:id,favorite:m.favorite,tags:m.tags});const a=state.assets.find(x=>x.id===id);if(a)Object.assign(a,result);if(local[id]?.rev===rev){local[id]={...result,pending:false,rev};store()}}}catch(e){/* Local copy remains pending until the next refresh. */}finally{syncing=false}}
const dlg=document.createElement('dialog');dlg.id='mmTagEditor';dlg.innerHTML='<form method="dialog"><div class="mm-edit-head"><h2>素材标签</h2><button type="button" class="ghost" data-mm-close aria-label="关闭标签编辑">关闭</button></div><p class="muted" id="mmTagName"></p><label for="mmTagInput">用逗号分隔，最多 8 个标签</label><input id="mmTagInput" maxlength="200" placeholder="例如：常用、花冠、托腮" autocomplete="off"><p class="muted">每个标签最多 20 字。留空可移除标签。</p><p class="mm-error" role="alert"></p><div class="mm-edit-actions"><button type="button" class="ghost" data-mm-close>取消</button><button type="submit">保存标签</button></div></form>';document.body.append(dlg);let editing=null;dlg.querySelectorAll('[data-mm-close]').forEach(b=>b.onclick=()=>dlg.close());dlg.querySelector('form').onsubmit=e=>{e.preventDefault();const tags=[...new Set($('mmTagInput').value.split(/[,，、\n]/).map(x=>x.trim()).filter(Boolean))];if(tags.length>8||tags.some(t=>t.length>20||/[\x00-\x1f]/.test(t))){dlg.querySelector('.mm-error').textContent='最多 8 个标签，每个 1–20 字，请勿包含控制字符。';return}if(change(editing,{tags}))dlg.close()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-mm-star],[data-mm-tag]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const id=b.dataset.mmStar||b.dataset.mmTag,a=state.assets.find(x=>x.id===id);if(!a)return;if(b.dataset.mmStar)change(id,{favorite:!meta(a).favorite});else{editing=id;$('mmTagName').textContent=a.name;$('mmTagInput').value=meta(a).tags.join('，');dlg.querySelector('.mm-error').textContent='';dlg.showModal();$('mmTagInput').focus()}},true);
const originalRender=renderLibrary;renderLibrary=function(...args){const scroll=views.map(v=>$(v.id)?.scrollTop||0);const result=originalRender.apply(this,args);decorate();views.forEach((v,i)=>{if($(v.id))$(v.id).scrollTop=scroll[i]});return result};const originalRefresh=refresh;refresh=async function(...args){const result=await originalRefresh.apply(this,args);decorate();sync();return result};window.addEventListener('storage',e=>{if(e.key!==key)return;try{local=JSON.parse(e.newValue||'{}');decorate()}catch(_){}});decorate();sync();
})();
