const c=$('sfCanvas'),ctx=c.getContext('2d'),f={request:0,scene:null,product:null,base:null,clean:null,fg:null,t:null,q:null,x:.5,y:.35,scale:.34,angle:0,mask:document.createElement('canvas'),dirty:false,clear:false,paint:false,drag:null,previewed:false};
