function img(url){return new Promise((resolve,reject)=>{const i=new Image;i.onload=()=>resolve(i);i.onerror=()=>reject(Error('图片读取失败'));i.src=url})}
function crop(im){const t=document.createElement('canvas');t.width=im.naturalWidth;t.height=im.naturalHeight;const x=t.getContext('2d');x.drawImage(im,0,0);const data=x.getImageData(0,0,t.width,t.height).data;let x0=t.width,y0=t.height,x1=-1,y1=-1;for(let y=0;y<t.height;y++)for(let a=0;a<t.width;a++)if(data[(y*t.width+a)*4+3]){x0=Math.min(x0,a);y0=Math.min(y0,y);x1=Math.max(x1,a);y1=Math.max(y1,y)}if(x1<0)throw Error('立牌透明图为空');const out=document.createElement('canvas');out.width=x1-x0+1;out.height=y1-y0+1;out.getContext('2d').drawImage(t,x0,y0,out.width,out.height,0,0,out.width,out.height);return out}
