async function load(){const request=++f.request,scene=$('sfScene').value,product=$('sfProduct').value;msg('正在读取场景…');const [r,base,fg]=await Promise.all([api('/api/fidelity/get',{scene,product}),img('/media/'+scene),img('/media/'+product)]);if(request!==f.request)return;Object.assign(f,{scene,product,base,clean:null,fg:crop(fg),t:r.template||{},dirty:false,clear:false,paint:false,previewed:false});c.width=base.naturalWidth;c.height=base.naturalHeight;f.mask.width=c.width;f.mask.height=c.height;if(r.mask){const m=await img('data:image/png;base64,'+r.mask);if(request!==f.request)return;f.mask.getContext('2d').drawImage(m,0,0)}if(f.t.clean_asset)f.clean=await img('/media/'+f.t.clean_asset);if(request!==f.request)return;f.q=f.t.quad;if(f.q){f.x=f.q.reduce((s,p)=>s+p[0],0)/4;f.y=f.q.reduce((s,p)=>s+p[1],0)/4;const dx=(f.q[1][0]-f.q[0][0])*c.width,dy=(f.q[1][1]-f.q[0][1])*c.height;f.scale=Math.hypot(dx,dy)/c.width;f.angle=Math.atan2(dy,dx)*180/Math.PI}else{f.angle=0;f.scale=Math.min(.34,.65*c.height/c.width*f.fg.width/f.fg.height);f.x=.5;f.y=.43;f.q=rect()}for(const [id,v]of [['sfScale',f.scale],['sfAngle',f.angle],['sfShadow',f.t.shadow??.15],['sfRim',f.t.rim??.1]])$(id).value=v;$('sfResult').hidden=true;$('sfStatus').textContent=r.ready?'已准备，可重复套用':'尚未确认干净背景';draw();msg('拖动调整摆放，准备干净背景后预览并保存。')}
async function save(extra={}){if(!f.scene||!f.fg)throw Error('请先读取场景');const body={scene:f.scene,quad:f.q,aspect:f.t.quad?f.t.aspect:f.fg.width/f.fg.height,anchor:f.t.anchor??.72,shadow:Number($('sfShadow').value),rim:Number($('sfRim').value),...extra};if(f.dirty)body.mask=f.mask.toDataURL('image/png').split(',')[1];if(f.clear)body.clear_mask=true;f.t=await api('/api/fidelity/save',body);f.dirty=false;f.clear=false;return f.t}
