const confirm=document.createElement('dialog');confirm.style.cssText='width:min(430px,calc(100vw - 32px));padding:24px;border:1px solid #dfe5e9;border-radius:16px';confirm.innerHTML='<h3>确认彻底删除？</h3><p id="purgeName"></p><p class="muted">无法恢复。只清理平台内部图片及关联导出，不删除你外部目录里的原文件。仍有引用时会阻止操作。</p><div class="actions"><button class="ghost" id="purgeCancel">取消</button><button class="primary" id="purgeConfirm">确认永久删除</button></div>';document.body.append(confirm);let purging=null;$('purgeCancel').onclick=()=>confirm.close();$('purgeConfirm').onclick=()=>withButton($('purgeConfirm'),async()=>{try{await change([purging],'purge');confirm.close();message('已彻底删除。')}catch(e){message(e.message,true)}});
